-- Pasos iniciales del plan: 5 por pilar, con los niveles a los que aplican.
-- Generado con un script; para cambiar el contenido, crear una nueva migración.


-- Genera el plan de quienes ya completaron el diagnóstico, con su intento más reciente
select public.rebuild_plan(a.user_id, a.id)
from (
  select distinct on (user_id) user_id, id
  from public.diagnostic_attempts
  order by user_id, completed_at desc
) a;
