insert into public.plan_step_templates (pillar, position, levels, title, description) values
  ('psychology', 1, array['low', 'medium', 'high']::public.score_level[], '{"es": "Escribe tus 3 metas para los próximos 12 meses", "en": "Write down your 3 goals for the next 12 months"}'::jsonb, '{"es": "Que sean concretas, medibles y con fecha.", "en": "Make them concrete, measurable and time-bound."}'::jsonb),
