  ('psychology', 4, array['low']::public.score_level[], '{"es": "Practica 5 minutos de respiración consciente cada día durante 7 días", "en": "Practice 5 minutes of mindful breathing daily for 7 days"}'::jsonb, '{"es": "Por ejemplo: inhala 4 segundos, sostén 4, exhala 6.", "en": "For example: inhale 4 seconds, hold 4, exhale 6."}'::jsonb),
  ('psychology', 5, array['medium', 'high']::public.score_level[], '{"es": "Elige un hábito clave y hazlo 21 días seguidos", "en": "Pick one key habit and do it 21 days in a row"}'::jsonb, '{"es": "Márcalo cada día en un calendario visible.", "en": "Mark it every day on a visible calendar."}'::jsonb),
