  ('finance', 2, array['low', 'medium']::public.score_level[], '{"es": "Arma un presupuesto mensual simple", "en": "Build a simple monthly budget"}'::jsonb, '{"es": "Ingresos, gastos fijos, gastos variables y ahorro.", "en": "Income, fixed costs, variable costs and savings."}'::jsonb),
