  ('fitness', 1, array['low', 'medium', 'high']::public.score_level[], '{"es": "Mide tu punto de partida", "en": "Measure your starting point"}'::jsonb, '{"es": "Peso, medida de cintura y una foto de frente y de perfil.", "en": "Weight, waist measurement and a front and side photo."}'::jsonb),
